description:
Write a class `Emitter<Events>` where `Events` maps each event name to the type of its payload:

```typescript
type AppEvents = { login: { user: string }; logout: undefined; error: Error };

const bus = new Emitter<AppEvents>();
const off = bus.on("login", e => console.log(e.user));   // e is { user: string }
bus.emit("login", { user: "ada" });
off();                                                    // stops listening
```

- `on<K extends keyof Events>(name: K, listener: (payload: Events[K]) => void): () => void` adds a listener and returns a function that removes it.
- `emit<K extends keyof Events>(name: K, payload: Events[K]): number` calls every listener of that event in the order they were added and returns how many were called.

starter.solution.ts:
class Emitter {
  on(name, listener) {
    return () => {};
  }

  emit(name, payload) {
    return 0;
  }
}

solution.solution.ts:
class Emitter<Events> {
  #listeners = new Map<keyof Events, Array<(payload: never) => void>>();

  on<K extends keyof Events>(name: K, listener: (payload: Events[K]) => void): () => void {
    const list = this.#listeners.get(name) ?? [];
    list.push(listener as (payload: never) => void);
    this.#listeners.set(name, list);
    return () => {
      const current = this.#listeners.get(name) ?? [];
      this.#listeners.set(name, current.filter(l => l !== listener));
    };
  }

  emit<K extends keyof Events>(name: K, payload: Events[K]): number {
    const list = [...(this.#listeners.get(name) ?? [])] as Array<(payload: Events[K]) => void>;
    for (const listener of list) listener(payload);
    return list.length;
  }
}

unitTests:
type AppEvents = { login: { user: string }; logout: undefined; error: Error };

test("listeners get their payload in order", () => {
  const bus = new Emitter<AppEvents>();
  const seen: string[] = [];
  bus.on("login", e => seen.push(`a:${e.user}`));
  bus.on("login", e => seen.push(`b:${e.user}`));
  bus.on("logout", () => seen.push("bye"));
  checkEq(bus.emit("login", { user: "ada" }), 2);
  checkEq(bus.emit("logout", undefined), 1);
  checkEq(bus.emit("error", new Error("x")), 0);
  checkEq(seen, ["a:ada", "b:ada", "bye"]);
});

test("unsubscribing", () => {
  const bus = new Emitter<AppEvents>();
  let count = 0;
  const off = bus.on("logout", () => count++);
  bus.emit("logout", undefined);
  off();
  bus.emit("logout", undefined);
  checkEq(count, 1);
});

